const mongoose = require("mongoose");

// A frozen exchange rate for one checkout attempt. Generated by
// POST /api/checkout/quote and looked up again — never recomputed — when the
// payment is verified, so whatever amount Flutterwave actually charges is
// checked against a rate that cannot have moved since checkout was initiated.
// Deliberately stores only the rate, not a precomputed price total: nights,
// quantity, hot-deal discount, and caution fee are already correctly computed
// fresh server-side in controllers/version1/reservation.js at booking time -
// this just supplies the source->guest currency rate for that math to use.
// See utilities/currency_utility.js and controllers/version1/reservation.js.
const checkoutQuoteSchema = new mongoose.Schema(
  {
    txRef: { type: String, required: true, unique: true },
    roomId: { type: mongoose.Schema.Types.ObjectId, ref: "Rooms", required: true },
    sourceCurrency: { type: String, required: true, uppercase: true },
    guestCurrency: { type: String, required: true, uppercase: true },
    rate: { type: Number, required: true },
    createdOn: { type: Date, required: true, immutable: true },
    // Mongo TTL index below auto-deletes the document at this timestamp -
    // an expired quote simply won't be found by reservation.js, which fails
    // closed (rejects the booking) rather than trusting a stale conversion.
    expiresAt: { type: Date, required: true },
  },
  {
    versionKey: false,
    toObject: {
      virtuals: true,
      transform: function (doc, ret) {
        delete ret._id;
        delete ret.roomId;
      },
    },
    toJSON: {
      virtuals: true,
      transform: function (doc, ret) {
        delete ret._id;
        delete ret.roomId;
      },
    },
  }
);

checkoutQuoteSchema.virtual("id").get(function () {
  return this._id.toHexString();
});

checkoutQuoteSchema.index({ expiresAt: 1 }, { expireAfterSeconds: 0 });

module.exports = mongoose.model("CheckoutQuote", checkoutQuoteSchema);
